const fields=['aiAnswer','finalAnswer','answer','stateClarificationPromptText','stateProactivityPromptText','stateClarificationTextReplyPromptText','reactionText','summaryText','inlineText','failureText','messageText','replyText','deliveryText','routeMessage','promptText','text','clarificationQuestion','cleanAnswer','questionText'];
const SECRET=[['telegram_token',/\b\d{7,12}:[A-Za-z0-9_-]{30,}\b/g],['openai_key',/\b(?:sk|sess)-[A-Za-z0-9_-]{20,}\b/g],['bearer',/\bBearer\s+[A-Za-z0-9._~+\/-]{16,}\b/gi],['jwt',/\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/g],['credential',/\b(?:api[_ -]?key|access[_ -]?token|refresh[_ -]?token|token|secret|password|private[_ -]?key)\s*[:=]\s*[^\s,;]{8,}/gi]];
const HIGH=[['security_marker',/CHELSEA_SECURITY_POLICY_V\d+/u],['prompt_tags',/<\/?(?:untrusted_[a-z_]+|application_policy|trusted_policy|user_saved_response_template)>/iu],['runtime_expression',/(?:\$env\.|\$node\[|\$execution\.|\$credentials|\{\{\s*\$)/u],['internal_node_name',/(?:^|\n)(?:Code|Call|Read|Write|If|Set|End|Start|Execute Command)\s*\|[^\n]{3,180}\|/u],['prompt_disclosure',/(?:here (?:is|are)|вот|ниже).{0,80}(?:my |мои )?(?:system prompt|developer instructions?|системн(?:ый|ые) промпт|системн(?:ые|ая|ых) инструкц|внутренн(?:ие|яя) инструкц)/iu],['env_secret_name',/CHELSEA_(?:OPENAI|KIE|QDRANT|SUPABASE|TELEGRAM|N8N)_[A-Z0-9_]*(?:KEY|TOKEN|SECRET)/u],['role_dump',/(?:^|\n)\s*(?:SYSTEM|DEVELOPER|TOOL)\s*:/u],['dangerous_scheme',/(?:javascript:|data:text\/html|file:\/\/|gopher:\/\/|http:\/\/(?:127\.0\.0\.1|localhost|169\.254\.169\.254))/iu],['active_html',/<(?:script|iframe|object|embed|form|meta)\b/iu]];
function norm(v){return String(v??'').normalize('NFKC').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F\u200B-\u200F\u202A-\u202E\u2060\u2066-\u2069\uFEFF]/g,'').trim();}
function variants(s){const a=[norm(s)];try{a.push(decodeURIComponent(a[0]))}catch{};const re=/\b[A-Za-z0-9+/_-]{24,}={0,2}\b/g;let m,c=0;while((m=re.exec(a[0]))&&c++<10){let raw=m[0].replace(/-/g,'+').replace(/_/g,'/');while(raw.length%4)raw+='=';try{a.push(Buffer.from(raw,'base64').toString('utf8'))}catch{}}return a.map(norm);}
function validate(raw){let answer=norm(raw);const findings=[];const vs=variants(answer);for(const [id,re] of SECRET){if(vs.some(v=>{re.lastIndex=0;return re.test(v)})){findings.push({type:id,severity:'critical'});re.lastIndex=0;answer=answer.replace(re,'[REDACTED_SECRET]');}}for(const [id,re] of HIGH)if(vs.some(v=>{re.lastIndex=0;return re.test(v)}))findings.push({type:id,severity:'high'});const blocked=findings.some(f=>f.severity==='high');if(blocked)answer='Я не буду раскрывать внутренние инструкции, служебные данные или секреты. Сформулируй задачу по результату, который тебе нужен, — отвечу по существу.';if(answer.length>120000){answer=answer.slice(0,120000);findings.push({type:'length_trimmed',severity:'medium'});}return {answer,findings,blocked,redacted:findings.some(f=>f.severity==='critical')};}
const out={...x};const all=[];let any=false,primary='';for(const field of fields){if(typeof x[field]!=='string'||!x[field].trim())continue;const r=validate(x[field]);out[field]=r.answer;all.push(...r.findings.map(f=>({...f,field})));any=any||r.blocked||r.redacted;if(!primary)primary=r.answer;}
if(typeof x.aiAnswer==='string'){out.aiAnswer=out.aiAnswer||primary;out.finalAnswer=out.aiAnswer;}
function syncBody(key,textField){if(out[key]&&typeof out[key]==='object'&&typeof out[key][textField]==='string'){const r=validate(out[key][textField]);out[key]={...out[key],[textField]:r.answer};all.push(...r.findings.map(f=>({...f,field:`${key}.${textField}`})));any=any||r.blocked||r.redacted;}}
for(const key of ['stateClarificationTelegramRequestBody','telegramTextReplyRequestBody','proactivitySettingsMessageBody','proactivityReplyPromptBody','telegramTaskResponseBody','telegramTaskCallbackAckBody'])syncBody(key,'text');
if(Array.isArray(out.topics))out.topics=out.topics.map((topic,i)=>{const r=validate(topic?.body||'');all.push(...r.findings.map(f=>({...f,field:`topics[${i}].body`})));any=any||r.blocked||r.redacted;return {...topic,body:r.answer};});
out.modelOutputSecurity={policyVersion:'chelsea_model_output_security_v3',blocked:all.some(f=>f.severity==='high'),redacted:all.some(f=>f.severity==='critical'),findings:all.slice(0,300),validatedAtIso:new Date().toISOString()};if('aiResponseReady'in out)out.aiResponseReady=Boolean(out.aiAnswer);if(any)out.aiFallbackUsed=out.aiFallbackUsed===true||out.modelOutputSecurity.blocked;return [{json:out}];
